lib/app/http/controllers/auth.controller.dart<pre><code>import 'package:blog/app/dtos/login_user/login_user.dto.dart';
import 'package:blog/app/dtos/register_user/register_user.dto.dart';
import 'package:blog/app/models/user/user.model.dart';
import 'package:dox_auth/dox_auth.dart';
import 'package:dox_core/dox_core.dart';

@Inject()
class AuthController {
  /// POST /api/auth/register
  Future&lt;DoxResponse&gt; register(RegisterUser body) async {
    User user = User()
      ..name = body.name
      ..email = body.email
      ..password = await Hash.makeAsync(body.password);
    await user.save();

    String? token = Auth().login(user);
    return response(&lt;String, dynamic&gt;{
      'token': token,
      'user': user,
    }).statusCode(201);
  }

  /// POST /api/auth/login
  Future&lt;Map&lt;String, dynamic&gt;&gt; login(LoginUser body) async {
    Auth auth = Auth();
    String? token = await auth.attempt(&lt;String, dynamic&gt;{
      'email': body.email,
      'password': body.password,
    });
    if (token == null) {
      throw UnAuthorizedException(message: 'Wrong email or password');
    }
    return &lt;String, dynamic&gt;{'token': token, 'user': auth.user&lt;User&gt;()};
  }

  /// GET /api/auth/user
  User? user(DoxRequest req) {
    return req.auth?.user&lt;User&gt;();
  }
}
</code></pre> <ul> <li><code>Hash.makeAsync()</code> makes a bcrypt hash. It runs in another isolate, so other requests do not wait. Never save a plain password.</li> <li><code>Auth().attempt()</code> finds the user by email and checks the password. It gives a token, or <code>null</code>.</li> <li><code>Auth().login(user)</code> gives a token without a password check. Register uses it, because the user was just made.</li> </ul>
